const r = await tools.exec_command({
  cmd: "$env:PYTHONUTF8='1'; [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new(); $py = 'C:\Users\24243\.cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe'; $code = @'
import sys,csv,json
from collections import defaultdict,Counter
from openpyxl import load_workbook
ss_path,sc_path,wb_path,vc_path=sys.argv[1:5]

def n(v):
 s='' if v is None else str(v).strip()
 return s[2:-1] if s.startswith('="') and s.endswith('"') else s

def xrows(p,s):
 ws=load_workbook(p,read_only=True,data_only=True)[s]; it=ws.iter_rows(values_only=True); h=[n(x) for x in next(it)]
 return [dict(zip(h,[n(x) for x in r])) for r in it if any(n(x) for x in r)]
def crows(p,d):
 with open(p,encoding='utf-8-sig',newline='') as f:return [{k:n(v) for k,v in r.items()} for r in csv.DictReader(f,delimiter=d)]
ss=xrows(ss_path,'Competitor-US-Last-30-days'); base=xrows(wb_path,'汇总(26款)'); sc=crows(sc_path,'\t'); vc=crows(vc_path,',')
ssby={r['ASIN']:r for r in ss}; targets={r['VC-ASIN'] for r in base}
family=defaultdict(list)
for r in ss:
 p=r.get('父ASIN') or r.get('ASIN'); family[p].append(r)
multi={p:rs for p,rs in family.items() if len(rs)>1}
identical=sum(len({(r.get('评分'),r.get('评分数')) for r in rs})==1 for rs in multi.values())
target_fams=defaultdict(list)
for a in targets:
 r=ssby[a]; target_fams[r.get('父ASIN') or a].append(a)
sc_targets=[r for r in sc if r.get('asin1') in targets]
vc_targets=[r for r in vc if r.get('ASIN') in targets]
print(json.dumps({
 'seller_sprite_multi_child_families':len(multi),
 'multi_child_families_with_identical_rating_review_across_exported_children':identical,
 'target_parent_families':{p:{'children':sorted(asins),'rating_review_pairs':sorted({(ssby[a].get('评分'),ssby[a].get('评分数')) for a in asins})} for p,asins in target_fams.items()},
 'sc_target_rows':len(sc_targets),'sc_target_fulfillment':dict(Counter(r.get('fulfillment-channel') for r in sc_targets)),'sc_target_status':dict(Counter(r.get('status') for r in sc_targets)),
 'vc_target_rows':len(vc_targets),'vc_target_status':dict(Counter(r.get('状态') for r in vc_targets)),'vc_target_inventory':dict(Counter(r.get('可售商品') for r in vc_targets)),
},ensure_ascii=False,indent=2))
